  "exports.eyebrow": "Data",
  "exports.title": "Eksport & sandaran",
  "exports.subtitleStart": "Muat turun sentiasa terhad kepada",
  "exports.subtitleRest": ". Setiap fail dilabelkan dengan nama perniagaan dan tarikh ia dibuat.",
  "exports.createBusinessFirst": "Cipta perniagaan dahulu — eksport tergolong dalam perniagaan, bukan aplikasi.",
  "exports.lockedTitle": "Eksport CSV dan Excel ialah ciri Business",
  "exports.lockedDesc": "Ruang kerja anda berada pada pelan Essentials. Business menambah eksport CSV dan Excel, penilaian stok, produk dan kakitangan tanpa had, pembekal, pembelian dan bundel.",
  "exports.seeBusiness": "Lihat apa yang disertakan dalam Business",
  "exports.whatTheseAre": "Apakah fail ini",
  "exports.about1": "Setiap set data hadir sebagai CSV atau buku kerja Excel sebenar (.xlsx) — buku kerja inventori penuh hanya Excel, dengan satu helaian bagi setiap set data. Fail CSV dibuka dalam Excel, Numbers, Google Sheets dan kebanyakan aplikasi stok. Teks UTF-8, koma dalam petikan, pemisah baris dalam nota dan sifar di hadapan dalam kod semuanya dikekalkan, dan sel yang bermula seperti formula dineutralkan supaya hamparan membukanya sebagai teks.",
  "exports.about2": "Dalam fail Excel, SKU, UPC, ISBN dan barkod ialah sel teks — tidak pernah notasi saintifik dan tidak pernah sifar dipangkas — dengan lebar lajur, penapis pengepala dan format mata wang atau kuantiti digunakan. Buku kerja inventori penuh menyimpan produk, paras stok, lokasi dan pergerakan pada helaian berasingan.",
  "exports.about3": "Eksport yang sangat besar berhenti pada 20,000 baris bagi setiap set data — apabila itu berlaku nama fail menyatakan demikian (truncated-20000), jadi fail separa tidak pernah disangka lengkap.",
  "exports.about4": "Sandaran ialah gambar keadaan data anda, bukan pemulihan satu klik. Memulihkannya ialah kerja manual yang disemak dahulu, jadi simpan fail dengan selamat — tiada apa-apa dalam aplikasi yang dapat mencipta semula perniagaan yang dipadamkan daripadanya lagi. Kod aplikasi dan sandaran platform Base44 dikendalikan berasingan daripada fail ini.",
  "exports.about5": "Foto dan lampiran disenaraikan sebagai pautan tersimpannya — fail imej itu sendiri tidak dimasukkan ke dalam muat turun.",
  "exports.backupTitle": "Sandaran penuh",
  "exports.backupDesc": "Satu fail dengan produk perniagaan ini, lokasi, paras stok, lejar pergerakan lengkap, pembekal, pembelian, pesanan, pemulangan, kiraan dan penyenaraian — ditambah tetapan profilnya. Simpannya di tempat yang anda kawal.",
  "exports.backupIncludes1": "Produk, kod, kos dan nota",
  "exports.backupIncludes2": "Lokasi dan kuantiti bagi setiap lokasi",
  "exports.backupIncludes3": "Setiap pergerakan, dengan pelaku dan masa",
  "exports.backupIncludes4": "Pembelian, pesanan, pemulangan dan kiraan",
