  "import.title": "Pusat import",
  "import.subtitleStart": "Tiga operasi hamparan berasingan, supaya pembetulan harga tidak boleh tiba sebagai penerimaan stok. Semuanya sampai ke",
  "import.subtitleRest": " sahaja, dan tiada apa-apa yang ditulis sehingga semakan percubaan telah lulus.",
  "import.createBusinessFirst": "Cipta perniagaan dahulu — produk yang diimport tergolong dalam perniagaan.",
  "import.createBusinessFirstShort": "Cipta perniagaan dahulu.",
  "import.whatEachDoes": "Apa yang setiap operasi lakukan",
  "import.createTitle": "Cipta produk baharu",
  "import.createDesc": "menambah baris yang belum ada dalam katalog. SKU dan barkod pendua yang sudah digunakan dilangkau, dan stok pembukaan boleh sampai di lokasi yang anda pilih sebagai penerimaan.",
  "import.updateTitle": "Kemas kini produk sedia ada",
  "import.updateDesc": "memadankan setiap baris mengikut SKU atau ID rekod dan menunjukkan nilai lama di samping nilai baharu yang dicadangkan. Sel kosong membiarkan nilai yang disimpan sahaja melainkan anda meminta kosong dikosongkan, dan kuantiti tidak pernah disentuh.",
  "import.receiveModeTitle": "Terima stok",
  "import.receiveModeDesc": "menambah kuantiti yang tiba ke satu lokasi dan menulis penerimaan ke lejar pergerakan untuk setiap baris. Setiap kelompok ditandakan, jadi helaian yang sama tidak boleh diterima dua kali.",
  "import.excelNote": "Buku kerja Excel (.xlsx) dibaca secara langsung — pilih lembaran kerja dan lajur dipadankan untuk anda. Kod kekal utuh: UPC yang disimpan sebagai teks mengekalkan digit dan sifar di hadapannya. Baris yang tidak dapat diimport disenaraikan dengan sebab",
