  "valuation.footnote": "Nilai kos menggunakan kos seunit semasa setiap produk, jadi menerima pada harga baharu menilai semula keseluruhan rak. Unit yang ditahan masih dikira di sini — ia di tangan, cuma dijanjikan kepada pesanan. Wang yang tiada tidak pernah dianggap sifar; biarkan medan kosong sehingga angka diketahui.",
