  "print.templateIsBusiness": "{label} ialah ciri Business",
  "print.supplierBlockedDesc": "Dokumen pembekal mengikut pelan Business — pembekal, pembelian dan pesanan belian. Semua yang anda ada kini terus berfungsi.",
  "print.seeBusiness": "Lihat apa yang disertakan dalam Business",
  "print.nothingToPrint": "Tiada apa-apa untuk dicetak lagi",
  "print.pickOrderHint": "Pilih pesanan belian dari senarai untuk melihat pratonton dokumen.",
  "print.pickCustomerOrderHint": "Pilih pesanan pelanggan dari senarai untuk melihat pratonton dokumen.",
  "print.pickReturnHint": "Pilih pemulangan yang dilogkan dari senarai untuk melihat pratonton dokumen.",
  "print.chooseStyleHint": "Pilih gaya, kemudian pilih produk dari senarai. Pratonton menunjukkan tepat apa yang keluar dari pencetak.",
  "print.howToReach": "Cara mencapai pencetak anda",
  "print.howIntro": "Aplikasi ini bersambung ke pencetak yang anda sudah miliki — ia bukan pencetak itu sendiri. Terdapat empat cara untuk mencapainya, dan label dicetak pada kedua-dua pelan melalui mana-mana daripadanya. Slip pembungkusan, pesanan belian, dokumen pembekal dan laporan hanya Business, walau apa pun sambungannya.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "Dari halaman ini, pada Chrome atau Edge desktop dan pada Chrome Android: pilih pencetak label anda dan label dihantar terus kepadanya. Ia tidak berfungsi dalam Safari iOS — pada iPhone, pencetakan Bluetooth hadir bersama aplikasi mudah alih sebaliknya. Pencetak yang hanya bercakap Zebra ZPL atau bahasa Brother sendiri tidak akan memahami label yang dihantar halaman ini; itu disemak terhadap pencetak sebenar sebelum ia dipanggil berfungsi.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "Pasang pencetak pada Wi-Fi kedai anda, kemudian guna butang Cetak — ia mencetak melalui pencetak yang dipasang pada komputer ini, melalui rangkaian kedai. Pada iPhone, AirPrint terbina dalam: pencetak AirPrint pada Wi-Fi yang sama muncul sahaja dalam helaian cetakan, tiada kabel dan tiada aplikasi diperlukan, dan aplikasi tidak memerlukan kod khusus AirPrint. Pencetak mesti menyokong AirPrint (kebanyakan yang baharu menyokongnya) dan telefon serta pencetak mesti berada pada Wi-Fi yang sama.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "Sambungkan pencetak ke rangkaian kedai anda dengan kabel Ethernet, pasangkannya pada komputer, dan cetak melalui butang Cetak. Ethernet ialah laluan desktop dan komputer — iPhone tidak menggunakan kabel Ethernet.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "Pasangkan pencetak ke komputer dengan kabelnya dan guna butang Cetak — ia mencetak melalui pencetak yang dipasang di situ. Pada telefon Android dengan kabel USB OTG, butang USB di atas bercakap terus dengan pencetak. iPhone tidak boleh mencetak melalui USB secara langsung — tiada WebUSB di situ — jadi guna Wi-Fi / AirPrint, atau Bluetooth dari aplikasi mudah alih.",
  "print.howCordsLead": "Kabel masih membantu iPhone, satu langkah jauh.",
  "print.howCordsBody": "Pencetak USB yang dipasangkan ke komputer kedai, atau pencetak Ethernet yang disambungkan ke rangkaian, muncul pada iPhone anda melalui Wi-Fi kedai (AirPrint / pencetak dikongsi) — kabel meletakkan pencetak pada rangkaian dengan kukuh, dan telefon mencapainya secara tanpa wayar.",
  "print.howOfflineLead": "Jika internet terputus,",
  "print.howOfflineBody": "label dan dokumen yang sudah ada pada halaman ini masih dicetak — butang Cetak, Label PDF, Bluetooth dan USB tidak memerlukan sambungan. Apa yang memerlukan internet ialah memuatkan halaman dan produknya terlebih dahulu. Mod luar talian penuh (bekerja dalam aplikasi tanpa sambungan langsung) ialah binaan berasingan yang lebih besar dan tidak dituntut di sini.",
