  "settings.cancelSubscription": "Batalkan Langganan",
  "settings.cancelTerms.appleLink": "Arahan pembatalan Apple",
  "settings.cancelTerms.googlePlayLink": "Arahan pembatalan Google Play",
  "settings.cancelTerms.graceTitle": "Selepas tempoh berbayar anda tamat — ihsan 15 hari, kemudian pemadaman:",
  "settings.cancelTerms.intro": "Ini ialah terma untuk langganan Luminous StockHaven berbayar. Pengebilan langganan laman web adalah melalui Stripe. Anda boleh membatalkan langganan anda sendiri pada bila-bila masa menggunakan butang Batalkan Langganan di bawah — tiada kelulusan kakitangan diperlukan. Permintaan pembatalan dan bayaran balik juga boleh dikendalikan melalui hubungan sokongan pelanggan rasmi, theluminousbookshop@outlook.com.",
  "settings.cancelTerms.noApprovalBody": "Anda boleh membatalkan langganan anda sendiri pada bila-bila masa. Tiada kelulusan kakitangan diperlukan. Pembaharuan akan datang hanya berhenti selepas pembekal pengebilan mengesahkan pembatalan.",
  "settings.cancelTerms.noApprovalTitle": "Batal tanpa kelulusan:",
  "settings.cancelTerms.paymentBody": "Untuk percubaan berbayar, percubaan tujuh hari memerlukan kaedah pembayaran semasa pendaftaran. Melainkan dibatalkan dalam tempoh akhir pembatalan percubaan yang berkenaan, pelan bulanan yang dipilih akan dicaj secara automatik selepas percubaan. Harga, tarikh pengebilan pertama, dan tarikh akhir pembatalan khusus pembekal mesti ditunjukkan semasa pendaftaran. Pengebilan percubaan adalah melalui Stripe.",
  "settings.cancelTerms.paymentTitle": "Kaedah pembayaran dan pembaharuan automatik:",
  "settings.cancelTerms.remainingBody": "Jika anda sudah membayar untuk tempoh pengebilan, anda boleh mengekalkan akses sehingga tarikh berbayar yang disahkan itu. Penamatan lebih awal memerlukan pengesahan pembekal yang sesuai dan sebarang pengendalian bayaran balik yang berkenaan. Akses percubaan percuma tamat mengikut tarikh penamatan percubaan yang disahkan pembekal.",
  "settings.cancelTerms.remainingTitle": "Akses yang tinggal:",
  "settings.cancelTerms.storesBody": "Jika anda pernah melanggan melalui Google Play atau Apple App Store, langganan anda dibilkan dan diurus oleh kedai itu. Anda mungkin perlu membatalkannya terus dalam bahagian langganan akaun Google atau Apple yang sama yang digunakan untuk melanggan. Membatalkan langganan laman web berasingan, menyahpasang aplikasi ini, atau meminta pemadaman akaun Luminous StockHaven tidak membatalkan langganan yang dibilkan kedai secara automatik. Semak resit pembelian anda untuk mengesahkan siapa yang mengenakan bayaran kepada anda.",
  "settings.cancelTerms.storesTitle": "Langganan Google Play dan Apple App Store (jika anda pernah melanggan melalui kedai):",
  "settings.cancelTerms.title": "Terma & Syarat Pembatalan",
  "settings.cancelTerms.trialBody": "Percubaan tujuh hari hanya boleh digunakan sekali bagi setiap pelanggan yang layak. Membatalkan percubaan atau langganan tidak memberikan percubaan lain; pelanggan yang kembali mesti memilih langganan berbayar.",
  "settings.cancelTerms.trialTitle": "Satu percubaan percuma:",
  "settings.canceled.endsOn": "Langganan ini dibatalkan dan tamat pada {date}. Anda kekal mendapat akses penuh sehingga itu.",
  "settings.delete.checking": "Menyemak permintaan pemadaman sedia ada…",
  "settings.delete.description": "Minta penyingkiran akaun log masuk Luminous StockHaven anda.",
  "settings.delete.dialogDescription": "Ini meminta semakan pemadaman akaun. Ia tidak serta-merta membuang log masuk atau inventori anda, dan ia tidak membatalkan sebarang langganan Stripe. Taip {word} untuk mengesahkan anda mahu menghantar permintaan.",
