  "staff.access.suspendedBody": "Pentadbir telah menggantung akaun kakitangan ini untuk perniagaan aktif. Minta mereka menetapkannya kembali kepada aktif, kemudian log masuk semula.",
  "staff.access.suspendedTitle": "Akses anda dijeda",
  "staff.addFirst": "Tambah ahli kakitangan pertama",
  "staff.addMember": "Tambah ahli kakitangan",
  "staff.emptyBody": "Tambah seseorang, beri mereka peranan dan kebenaran yang mengiringinya, dan mereka dijemput melalui e-mel untuk log masuk ke perniagaan ini.",
  "staff.emptyTitle": "Tiada kakitangan lagi",
  "staff.eyebrow": "Pasukan",
  "staff.how.p1": "Setiap ahli mempunyai peranan dan senarai kebenarannya sendiri, jadi anda boleh bermula dari peranan dan mengubah satu perkara tanpa mewujudkan peranan baharu. Mengedit peranan tidak menulis semula ahli yang sudah ada padanya — buka ahli untuk menggunakan semula lalai peranannya.",
  "staff.how.p2": "Peranan tersuai ialah ciri Business: Essentials menggunakan lima peranan terbina dalam (Pemilik, Pengurus, Kerani stok, Kerani jualan, Penonton).",
  "staff.how.p3": "Jemputan dihantar melalui e-mel. Ahli hanya boleh log masuk setelah mereka menerima, dan membuang seseorang dari senarai ini tidak memadamkan akaun aplikasi mereka.",
  "staff.how.p4": "Kedai ialah lokasi seseorang ditugaskan. Ia direkodkan pada kad mereka; apa yang mereka boleh buka masih ditentukan oleh peranan dan kebenaran mereka.",
  "staff.how.p5": "Kebenaran menentukan apa yang setiap orang boleh buka: item menu di luar peranan mereka disembunyikan, dan alamat yang disekat menunjukkan notis “bukan pada peranan anda” dan bukannya halaman. Perubahan dikenakan pada kali seterusnya orang itu memuatkan aplikasi; menggantung ahli mengunci mereka keluar sepenuhnya.",
  "staff.how.p6": "Pentadbir boleh melihat dan menukar semua data, mengurus pengguna dan peranan aplikasi, dan tidak pernah dihadkan oleh peranan kakitangan. Seseorang tanpa rekod kakitangan — pemilik perniagaan baharu — mengekalkan akses penuh.",
  "staff.howTitle": "Cara kakitangan dan peranan berfungsi",
