  "training.warningSentOn": "Amaran dihantar {date}",
  "auth.sameEmailNotice": "Sudah ada aplikasi kami daripada Google Play atau App Store? Gunakan e-mel yang sama di sini — e-mel yang anda gunakan untuk log masuk ke aplikasi — supaya kedai dan inventori anda ikut bersama anda. E-mel yang berbeza memulakan etalase yang serba baharu dan kosong.",
