  "rewards.redeem.help": "Taip kod yang ditunjukkan oleh ahli pasukan kepada anda. Setiap kod berfungsi sekali.",
  "rewards.redeem.placeholder": "Kod ganjaran",
  "rewards.redeem.submit": "Tandakan sebagai digunakan",
