  "rewards.status.active": "Sedia untuk digunakan",
  "rewards.status.redeemed": "Digunakan",
  "rewards.status.void": "Dibatalkan",
  "rewards.subtitle": "Ucapkan terima kasih dengan ganjaran — diskaun peratus, kad hadiah, atau apa-apa yang anda huraikan.",
  "rewards.title": "Ganjaran & insentif",
  "rewards.value.giftCard": "Kad hadiah {value}",
  "rewards.value.percentOff": "{percent}% diskaun di kedai",
  "rewards.void": "Batalkan",
  "rewards.voided": "Ganjaran dibatalkan.",
  "workforce.tab.rewards": "Ganjaran",
  "training.lessons.mgr-give-rewards.step1": "Buka Tenaga Kerja dan ketik Ganjaran. Pilih ahli pasukan, kemudian jenisnya: diskaun peratus di kedai, kad hadiah, atau sesuatu yang lain yang anda huraikan dengan perkataan anda sendiri.",
  "training.lessons.mgr-give-rewards.step2": "Beri ganjaran nama ringkas dan nota jika anda suka. Orang itu mendapat loceng serta-merta, dan ganjaran menunggu dalam Ganjaran saya mereka dengan kodnya sendiri.",
  "training.lessons.mgr-give-rewards.step3": "Sempadan, secara reka bentuk: anda memberi ganjaran kepada KAKITANGAN sahaja. Anda tidak boleh memberi ganjaran kepada diri sendiri atau pengurus lain — memberi ganjaran kepada pengurus ialah keputusan pemilik, dan aplikasi akan menolaknya dengan jelas.",
  "training.lessons.mgr-give-rewards.step4": "Di kaunter bayaran, taip kod yang ditunjukkan oleh ahli pasukan kepada anda dan tandakannya digunakan — setiap kod berfungsi sekali. Anda boleh membatalkan ganjaran yang anda berikan jika rancangan berubah; hadiah pemilik adalah milik pemilik untuk dibatalkan.",
  "training.lessons.mgr-give-rewards.title": "Memberi ganjaran kepada kakitangan anda",
  "training.lessons.owner-give-rewards.step1": "Ganjaran tinggal dalam Tenaga Kerja, pada tab Ganjaran, dan ia hanya untuk pelan Business — pada Essentials tab menunjukkan pintu terkunci, supaya pasukan anda boleh melihat apa yang ditawarkan oleh pelan yang lebih besar.",
  "training.lessons.owner-give-rewards.step2": "Anda boleh memberi ganjaran kepada SESIAPA dalam pasukan — kakitangan dan pengurus sama. Pilih orang itu, kemudian jenisnya: diskaun peratus di kedai (sebarang peratus yang anda pilih), kad hadiah ke mana-mana, atau sebarang insentif yang anda huraikan dengan perkataan anda sendiri.",
  "training.lessons.owner-give-rewards.step3": "Ganjaran tiba dengan kod sekali gunanya sendiri dan membunyikan loceng orang itu. Mereka menunjukkan kod di kaunter bayaran; pemilik atau pengurus menaipnya untuk menandakannya digunakan.",
  "training.lessons.owner-give-rewards.step4": "Slip ganjaran bercetak atau dikongsi hanya membawa nama perniagaan ANDA — tidak pernah nama aplikasi. Ia adalah ucapan terima kasih kedai anda, bukan iklan.",
  "training.lessons.owner-give-rewards.title": "Memberi ganjaran (pelan Business)",
  "training.lessons.owner-rewards-oversight.step1": "Pengurus anda juga boleh memberi ganjaran — kepada kakitangan sahaja. Aplikasi menolak pengurus memberi ganjaran kepada diri sendiri atau pengurus lain; memberi ganjaran kepada pengurus sentiasa keputusan anda.",
  "training.lessons.owner-rewards-oversight.step2": "Anda melihat setiap ganjaran dalam perniagaan dalam Sejarah ganjaran: siapa memberikannya, siapa mendapatnya, dan sama ada ia sedia, digunakan atau dibatalkan. Pengurus hanya melihat ganjaran yang mereka berikan dan yang mereka terima.",
  "training.lessons.owner-rewards-oversight.step3": "Anda boleh membatalkan sebarang ganjaran, termasuk yang diberikan oleh pengurus anda. Pengurus boleh membatalkan hadiah mereka sendiri, tetapi tidak pernah hadiah anda.",
  "training.lessons.owner-rewards-oversight.step4": "Setiap kod berfungsi tepat sekali, dan ganjaran yang dibatalkan tidak boleh digunakan — sejarah sentiasa menunjukkan bagaimana ganjaran berakhir.",
  "training.lessons.owner-rewards-oversight.title": "Menyelia ganjaran: pemberian pengurus anda",
  "training.lessons.staff-your-rewards.step1": "Apabila pengurus atau pemilik memberi anda ganjaran, loceng anda berbunyi. Buka Tenaga Kerja dan ketik Ganjaran untuk melihatnya di bawah Ganjaran saya.",
  "training.lessons.staff-your-rewards.step2": "Setiap ganjaran mempunyai kodnya sendiri. Simpan untuk diri sendiri — sesiapa yang menunjukkan kod di kaunter bayaran ialah orang yang menggunakan ganjaran.",
  "training.lessons.staff-your-rewards.step3": "Untuk menggunakannya, tunjukkan kod apabila anda membeli. Orang di kaunter bayaran menaipnya dan menandakannya digunakan — setiap kod berfungsi tepat sekali.",
  "training.lessons.staff-your-rewards.step4": "Ganjaran ialah layanan pelan Business. Jika kedai anda tiada pada Business, tab Ganjaran menunjukkan pintu terkunci sebaliknya — itu ialah pelan, bukan kesilapan.",
  "training.lessons.staff-your-rewards.title": "Ganjaran anda: mencari kod anda dan menggunakannya",
  "training.module.rewards": "Ganjaran & insentif",
